globalThis.process===void 0&&(globalThis.process={env:{},nextTick:function(e){setTimeout(e,0)},emit:function(){return!1}});import"react";import"react-dom";import"react/jsx-runtime";import"react-dom/client";var e={sender:`Gaia`,preview:`Γεια σας 👋 Ευχαριστούμε που επικοινωνήσατε. Θα σας απαντήσω σύντομα…`,ageLabel:`4ω`},t=JSON.parse('{"demo-news-1":{"title":"Pioneer 2026: κρατήστε την ημερομηνία","excerpt":"Επιστρέφουμε στο Σαν Φρανσίσκο στις 8 Οκτωβρίου. Άνοιγμα θυρών στις 9, κεντρική ομιλία στις 10.","body":"## Τι να περιμένετε\\n\\nΗ φετινή κεντρική ομιλία αφορά όσα κυκλοφορήσαμε ανοιχτά και όσα έρχονται. Ζωντανές επιδείξεις, όχι διαφάνειες.\\n\\n- **Ο οδικός χάρτης της Gaia** - πού κατευθύνεται η τεχνητή νοημοσύνη μας τα επόμενα δύο τρίμηνα.\\n- **Ιστορίες πελατών** - τρεις ομάδες μοιράζονται πώς μείωσαν στο μισό τον χρόνο πρώτης απάντησης.\\n- **Πρακτικά εργαστήρια** - φέρτε φορητό υπολογιστή και φτιάξτε ένα flow με τους μηχανικούς μας.\\n\\n## Πώς θα φτάσετε\\n\\nΟ χώρος είναι το Pier 27 Cruise Terminal, ακριβώς στο Embarcadero. Η κοντινότερη στάση BART είναι το Embarcadero, 12 λεπτά με τα πόδια δίπλα στο νερό.\\n\\n## Εισιτήρια\\n\\nΟι θέσεις early-bird είναι περιορισμένες και ανοίγουν την επόμενη εβδομάδα. Οι υπάρχοντες πελάτες έχουν προτεραιότητα, οπότε προσέξτε τα εισερχόμενά σας.\\n\\n> Δεν μπορείτε να έρθετε αυτοπροσώπως; Η κεντρική ομιλία μεταδίδεται ζωντανά και οι καταγραφές θα βρίσκονται εδώ το ίδιο βράδυ."},"demo-news-2":{"title":"Τι κυκλοφόρησε τον Απρίλιο","excerpt":"Τρεις νέοι ενεργοποιητές αυτοματισμού και πολύ ταχύτερη αναζήτηση στα εισερχόμενα.","body":"<p>Ο Απρίλιος ήταν ένας μεγάλος μήνας. Ορίστε όλα όσα κυκλοφόρησαν, με μια ματιά:</p>\\n<table>\\n<thead><tr><th>Τομέας</th><th>Τι άλλαξε</th><th>Γιατί έχει σημασία</th></tr></thead>\\n<tbody>\\n<tr><td>Αναζήτηση εισερχομένων</td><td>Άμεσα αποτελέσματα καθώς πληκτρολογείτε</td><td>50 χιλιάδες συνομιλίες, κάτω από 100 ms</td></tr>\\n<tr><td>Αυτοματισμός</td><td>Τρεις νέοι ενεργοποιητές</td><td>Εγκαταλελειμμένο καλάθι, επανεπίσκεψη σελίδας, ήσυχος επισκέπτης</td></tr>\\n<tr><td>Επεξεργαστής</td><td>Το πρόχειρο επιβιώνει σε αλλαγή καρτέλας</td><td>Τέλος στις χαμένες μισογραμμένες απαντήσεις</td></tr>\\n<tr><td>Σκοτεινή λειτουργία</td><td>Χωρίς λευκή λάμψη στην πρώτη εμφάνιση</td><td>Πιο καθαρή φόρτωση σε σκοτεινούς ιστότοπους</td></tr>\\n</tbody>\\n</table>\\n<p>Η νέα αναζήτηση σε δράση - τα αποτελέσματα εμφανίζονται πριν τελειώσετε το πληκτρολόγιο:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-search/1024/576\\" alt=\\"Αναζήτηση εισερχομένων που επιστρέφει αποτελέσματα άμεσα\\" />\\n<p>Πατήστε στην εικόνα για να τη δείτε από κοντά. Έχετε κάποιο αίτημα; Απαντήστε εδώ - τα διαβάζουμε όλα.</p>"},"demo-news-3":{"title":"Η Gaia μιλά πλέον 28 γλώσσες","excerpt":"Εντοπίστε αυτόματα τη γλώσσα του επισκέπτη ή καρφώστε μία. Χωρίς επιπλέον ρύθμιση.","body":"<p>Η Gaia απαντά πλέον σε 28 γλώσσες, που εντοπίζονται αυτόματα από το πρώτο μήνυμα του επισκέπτη. Οι ερωτήσεις που ακούμε πιο συχνά:</p>\\n<details><summary>Πώς λειτουργεί ο εντοπισμός γλώσσας;</summary><p>Η Gaia διαβάζει το αρχικό μήνυμα και απαντά στην ίδια γλώσσα. Αν τα άρθρα βοήθειάς σας υπάρχουν σε αυτή τη γλώσσα, τα παραθέτει· διαφορετικά απαντά από την πλησιέστερη αντιστοιχία και σας επισημαίνει το κενό.</p></details>\\n<details><summary>Μπορώ να επιβάλω μία μόνο γλώσσα;</summary><p>Ναι. Καρφώστε μία στο <strong>Ρυθμίσεις → ΑΙ → Γλώσσα</strong> και η Gaia θα τη διατηρεί ό,τι κι αν πληκτρολογήσει ο επισκέπτης.</p></details>\\n<details><summary>Τι βλέπουν οι χειριστές;</summary><p>Οι μεταγραφές παραμένουν στη γλώσσα της ομάδας σας, με το αρχικό μήνυμα να φυλάσσεται δίπλα στη μετάφραση.</p></details>\\n<p>Μια γρήγορη ματιά στη Gaia να αλλάζει γλώσσα στη μέση μιας συνομιλίας:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-lang/1024/576\\" alt=\\"Η Gaia απαντά σε πολλές γλώσσες\\" />"},"demo-news-4":{"title":"Στείλτε συνομιλίες απευθείας στο Slack","excerpt":"Συνδέστε οποιοδήποτε εισερχόμενο webhook σε ένα κανάλι Slack. Χωρίς κώδικα-κόλλα.","body":"## Σύνδεση με δύο κλικ\\n\\nΠηγαίνετε στο **Ενσωματώσεις → Slack**, πατήστε *Σύνδεση* και εγκρίνετε τα δικαιώματα. Επιλέξτε το κανάλι όπου θα καταλήγουν οι νέες συνομιλίες - οι περισσότερες ομάδες χρησιμοποιούν το `#support`.\\n\\n## Τι παίρνετε\\n\\n- Ένα μήνυμα Slack τη στιγμή που ξεκινά μια συνομιλία, με σύνδεσμο πίσω στα εισερχόμενα.\\n- Απαντήσεις χειριστών σε νήμα κάτω από το αρχικό μήνυμα.\\n- Απαντήστε απευθείας από το Slack και το στέλνουμε στον επισκέπτη σε πραγματικό χρόνο.\\n\\n## Και webhooks\\n\\nΣτέλνετε ήδη συμβάντα από τα δικά σας συστήματα; Στρέψτε οποιοδήποτε webhook στο κανάλι Slack και παραλείψτε εντελώς την προσαρμοσμένη ενσωμάτωση."},"demo-news-5":{"title":"Εισερχόμενα 2.0: ταξινόμηση χωρίς ποντίκι","excerpt":"Νέες συντομεύσεις για ανάθεση, αναβολή και επίλυση - όλα από το πληκτρολόγιο.","body":"<p>Τα Εισερχόμενα 2.0 είναι σχεδιασμένα πρώτα για το πληκτρολόγιο. Ορίστε το σκονάκι, ομαδοποιημένος ανάλογα με το τι κάνετε:</p>\\n<div data-type=\\"tabs\\">\\n<div data-type=\\"tab\\"><div data-tab-label>Πλοήγηση</div><ul><li><code>j</code> / <code>k</code> - επόμενη / προηγούμενη συνομιλία</li><li><code>g</code> και μετά <code>i</code> - μετάβαση στα εισερχόμενα</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>Ενέργεια</div><ul><li><code>e</code> - επίλυση</li><li><code>a</code> - ανάθεση σε εμένα</li><li><code>s</code> - αναβολή</li></ul></div>\\n<div data-type=\\"tab\\"><div data-tab-label>Σύνταξη</div><ul><li><code>Cmd+Enter</code> - αποστολή</li><li><code>/</code> - αποθηκευμένες απαντήσεις</li><li><code>Cmd+K</code> - παλέτα εντολών</li></ul></div>\\n</div>\\n<p>Τα επανασχεδιασμένα εισερχόμενα - όλα σε απόσταση ενός πλήκτρου:</p>\\n<img src=\\"https://picsum.photos/seed/wexio-inbox/1024/576\\" alt=\\"Τα επανασχεδιασμένα εισερχόμενα με έμφαση στο πληκτρολόγιο\\" />"},"demo-news-6":{"title":"Εξαγωγή και διαγραφή δεδομένων αυτοεξυπηρέτησης","excerpt":"Διαχειριστείτε αιτήματα δεδομένων επισκεπτών με ένα κλικ. Έτοιμο για GDPR από την αρχή.","body":"## Εξαγωγή\\n\\nΑπό το προφίλ οποιουδήποτε επισκέπτη, πατήστε **Εξαγωγή δεδομένων** για να δημιουργήσετε ένα πακέτο JSON με κάθε μήνυμα, συμβάν και χαρακτηριστικό που διατηρούμε γι\' αυτόν. Η λήψη γίνεται άμεσα και το αίτημα καταγράφεται για το αρχείο σας.\\n\\n## Διαγραφή\\n\\nΗ **Διαγραφή δεδομένων** αφαιρεί τον επισκέπτη και διαγράφει τα μηνύματά του από τα εισερχόμενα, την αναζήτηση και κάθε συνδεδεμένο CRM μέσω της ίδιας γέφυρας webhook. Η ενέργεια καταγράφεται και είναι μη αναστρέψιμη.\\n\\n## Για τον DPO σας\\n\\n- Κάθε εξαγωγή και διαγραφή φέρει χρονοσφραγίδα και απόδοση σε χρήστη.\\n- Οι περίοδοι διατήρησης ρυθμίζονται ανά workspace.\\n- Συμφωνία επεξεργασίας δεδομένων διατίθεται κατόπιν αιτήματος."},"demo-news-7":{"title":"Beta του SDK για κινητά: iOS και Android","excerpt":"Φέρτε την ίδια συνομιλία στη native εφαρμογή σας. Οι θέσεις beta άνοιξαν.","body":"## Μία συνομιλία, κάθε επιφάνεια\\n\\nΈνας επισκέπτης που ξεκινά συνομιλία στον ιστότοπό σας μπορεί να τη συνεχίσει στην εφαρμογή σας, συνδεδεμένος και με πλήρες ιστορικό. Η ίδια Gaia, οι ίδιοι χειριστές, τα ίδια εισερχόμενα.\\n\\n## Τι περιλαμβάνει το beta\\n\\n- Native launcher για SwiftUI και Jetpack Compose.\\n- Ειδοποιήσεις push για νέες απαντήσεις.\\n- Ουρά εκτός σύνδεσης, ώστε τα μηνύματα να στέλνονται όταν επανέλθει η σύνδεση.\\n\\n## Συμμετάσχετε\\n\\nΕντάσσουμε μια χούφτα ομάδες κάθε εβδομάδα. Απαντήστε εδώ με την πλατφόρμα σας και τον κατά προσέγγιση αριθμό μηνιαίων ενεργών χρηστών και θα σας στείλουμε κλειδί.\\n\\n> Το beta σημαίνει τραχιές άκρες. Κυκλοφορούμε διορθώσεις κάθε εβδομάδα και διαβάζουμε κάθε αναφορά σφάλματος."},"demo-news-8":{"title":"Δείτε ποιες απαντήσεις της ΑΙ πραγματικά δούλεψαν","excerpt":"Παρακολουθήστε αν κάθε απάντηση της Gaia οδήγησε σε επίλυση, παράδοση ή εγκατάλειψη.","body":"## Η νέα προβολή\\n\\nΤο **Αναλύσεις → Αποτελέσματα ΑΙ** αναλύει κάθε απάντηση της Gaia ανάλογα με το τι συνέβη μετά:\\n\\n- **Επιλύθηκε** - ο επισκέπτης πήρε ό,τι χρειαζόταν και έφυγε ευχαριστημένος.\\n- **Παραδόθηκε** - η Gaia πέρασε τη συνομιλία σε άνθρωπο.\\n- **Εγκατέλειψε** - ο επισκέπτης έκλεισε το widget χωρίς επίλυση.\\n\\n## Εικόνα ανά άρθρο\\n\\nΜπείτε σε οποιοδήποτε άρθρο βοήθειας για να δείτε πόσο συχνά το παραθέτει η Gaia και αν αυτές οι παραθέσεις οδηγούν σε επίλυση. Χαμηλή επίλυση σε άρθρο με μεγάλη επισκεψιμότητα συνήθως σημαίνει ότι το περιεχόμενο χρειάζεται επανεγγραφή, όχι η ΑΙ.\\n\\n## Δράστε\\n\\nΤαξινομήστε κατά ποσοστό εγκατάλειψης για να βρείτε τις ερωτήσεις με τις οποίες δυσκολεύεται περισσότερο η Gaia και προσθέστε ένα flow ή ένα πιο στοχευμένο άρθρο για να κλείσετε το κενό."},"tags":{"events":"Εκδηλώσεις","product":"Προϊόν","release":"Έκδοση","ai":"ΑΙ","languages":"Γλώσσες","integrations":"Ενσωματώσεις","slack":"Slack","inbox":"Εισερχόμενα","privacy":"Απόρρητο","security":"Ασφάλεια","mobile":"Κινητά","beta":"Beta","analytics":"Αναλύσεις"},"categories":{"company":"Εταιρεία","product":"Προϊόν","engineering":"Μηχανική"}}'),n=JSON.parse('{"categories":{"demo-cat-getting-started":{"title":"Ξεκινώντας","description":"Εγκαταστήστε το widget και ρυθμίστε την πρώτη σας συνομιλία."},"demo-cat-automation":{"title":"Αυτοματισμός","description":"Flows, ενεργοποιητές και η αυτόματη απάντηση της ΑΙ."},"demo-cat-integrations":{"title":"Ενσωματώσεις","description":"Συνδέστε το CRM, το Slack και το CMS σας."},"demo-cat-billing":{"title":"Χρέωση και πακέτα","description":"Επίπεδα τιμολόγησης, τιμολόγια και διαχείριση θέσεων."}},"articles":{"demo-article-install":{"title":"Εγκατάσταση του widget Wexio στον ιστότοπό σας","excerpt":"Ένα απόσπασμα 30 δευτερολέπτων που επικολλάτε πριν από την ετικέτα κλεισίματος </body>.","body":"## Προσθέστε το script φόρτωσης\\n\\nΕπικολλήστε αυτό το απόσπασμα σε κάθε σελίδα όπου θέλετε να εμφανίζεται το widget:\\n\\n```html\\n<script\\n  src=\\"https://cdn.wexio.io/widget/loader.js\\"\\n  data-public-key=\\"pk_live_YOUR_KEY\\"\\n><\/script>\\n```\\n\\nΟ φορτωτής εισάγει έναν πλωτό launcher στην κάτω δεξιά γωνία. Κάντε κλικ για να ανοίξετε το πάνελ συνομιλίας.\\n\\n## Επαληθεύστε την εγκατάσταση\\n\\n- Επισκεφθείτε μια σελίδα που περιλαμβάνει το απόσπασμα.\\n- Ανοίξτε την κονσόλα του προγράμματος περιήγησης.\\n- Θα πρέπει να δείτε `[wexio] widget mounted`.\\n\\n## Προσαρμόστε την εμφάνιση\\n\\nΤο widget διαβάζει τα χρώματα της επωνυμίας από τον πίνακα ελέγχου σας. Ενημερώστε τα στο **Ρυθμίσεις → Επωνυμία**.\\n\\n> Χρειάζεστε βοήθεια; Πατήστε \\"Χρειάζεστε ακόμα βοήθεια; Στείλτε μας μήνυμα\\" παρακάτω και θα σας καθοδηγήσουμε."},"demo-article-flows":{"title":"Φτιάξτε το πρώτο σας flow αυτοματισμού","excerpt":"Σύρετε, αφήστε και ξεκινήστε ένα bot καλωσορίσματος σε λιγότερο από πέντε λεπτά.","body":"## Τι είναι ένα flow;\\n\\nΈνα flow είναι ένα μικρό δέντρο βημάτων συνομιλίας - ερωτήσεις, απαντήσεις και συνθήκες - που εκτελείται κάθε φορά που ένας επισκέπτης ταιριάζει με έναν ενεργοποιητή.\\n\\n## Τρεις τύποι ενεργοποιητών\\n\\n1. **Ο επισκέπτης άνοιξε το widget** - καλωσορίστε όσους έρχονται για πρώτη φορά.\\n2. **Ο επισκέπτης έκανε μια ερώτηση** - η Gaia (ΑΙ) προσπαθεί να απαντήσει· αν δεν μπορεί, αναλαμβάνει το flow.\\n3. **Ελήφθη webhook** - το CMS ή η πλατφόρμα ηλεκτρονικού εμπορίου σας στέλνει ένα συμβάν· το flow ξεκινά στη σωστή συνομιλία.\\n\\n## Βέλτιστες πρακτικές\\n\\n- Κρατήστε τις πρώτες απαντήσεις κάτω από 80 χαρακτήρες.\\n- Προσφέρετε 2-3 chips γρήγορης απάντησης, όχι ερώτηση ελεύθερου κειμένου.\\n- Δώστε πάντα μια διέξοδο - *\\"Συνομιλία με άνθρωπο\\"*."},"demo-article-slack":{"title":"Προώθηση συνομιλιών στο Slack","excerpt":"Αντικατοπτρίστε κάθε νέα συνομιλία σε ένα κανάλι Slack της επιλογής σας.","body":"## Συνδέστε το workspace σας\\n\\nΣτο **Ενσωματώσεις → Slack** κάντε κλικ στο *Σύνδεση*. Θα ανακατευθυνθείτε στην οθόνη OAuth του Slack - εγκρίνετε τα αιτούμενα δικαιώματα (`chat:write`, `channels:read`).\\n\\n## Επιλέξτε κανάλι\\n\\nΜετά την εξουσιοδότηση, επιλέξτε το κανάλι προορισμού (ή δημιουργήστε ένα νέο, όπως το `#support`).\\n\\n## Τι προωθείται\\n\\n- Το αρχικό μήνυμα, με άμεσο σύνδεσμο πίσω στα εισερχόμενα του wexio.\\n- Οι απαντήσεις των χειριστών ως μηνύματα σε νήμα.\\n- Οι απαντήσεις των επισκεπτών σε πραγματικό χρόνο μέσω της γέφυρας SSE.\\n\\n## Αντίστροφη κατεύθυνση\\n\\nΟι χειριστές μπορούν να απαντούν *από* το Slack - το wexio παρακολουθεί τις απαντήσεις στα νήματα του Slack και τις στέλνει πίσω στο widget."},"demo-article-billing":{"title":"Ενημέρωση του πακέτου και των στοιχείων χρέωσης","excerpt":"Αλλάξτε επίπεδο, αλλάξτε κάρτα ή κατεβάστε τιμολόγια.","body":"## Πακέτα\\n\\n- **Free** - 1 widget, βασικά χαρακτηριστικά, σήμα \\"Powered by Wexio\\".\\n- **Standard** - απεριόριστα widgets, αυτοματισμοί, ενσωματώσεις.\\n- **Enterprise** - white-label, SLA, αποκλειστική υποστήριξη.\\n\\n## Αλλαγή πακέτου\\n\\n**Ρυθμίσεις → Χρέωση → Αλλαγή πακέτου**. Οι αναβαθμίσεις ισχύουν αμέσως· οι υποβαθμίσεις εφαρμόζονται στο τέλος του τρέχοντος κύκλου.\\n\\n## Τιμολόγια\\n\\nΚατεβάστε κάθε τιμολόγιο ως PDF από το **Χρέωση → Ιστορικό**. Στέλνουμε επίσης αντίγραφο με email σε κάθε ανανέωση."},"demo-article-theme":{"title":"Προσαρμογή του θέματος του widget","excerpt":"Ταιριάξτε το widget με την επωνυμία σας - χρώματα, καμπυλότητες, σκοτεινή λειτουργία.","body":"## Χρώματα επωνυμίας\\n\\nΣτο **Ρυθμίσεις → Επωνυμία**, ορίστε:\\n\\n- **Κύριο** - καθορίζει τον launcher, το κουμπί αποστολής και τους δακτυλίους εστίασης.\\n- **Φόντο** - την επιφάνεια του πάνελ (ανοιχτή) και το ζεύγος της για τη σκοτεινή λειτουργία.\\n\\n## Καμπυλότητες\\n\\nΕπιλέξτε από `sm`, `md`, `lg` για πιο έντονη ή πιο απαλή εμφάνιση. Η αλλαγή εφαρμόζεται ζωντανά σε κάθε widget σε κάθε σελίδα.\\n\\n## Σκοτεινή λειτουργία\\n\\nΠροεπιλογή = ακολουθεί την προτίμηση συστήματος του επισκέπτη. Καρφώστε το σε **πάντα ανοιχτό** ή **πάντα σκούρο** αν ο ιστότοπός σας δεν υποστηρίζει ο ίδιος σκοτεινή λειτουργία."},"demo-article-handoff":{"title":"Παράδοση από τη Gaia σε ανθρώπινο χειριστή","excerpt":"Όταν η ΑΙ δεν αρκεί - κατευθύνετε τον επισκέπτη σε συνάδελφο.","body":"## Ενεργοποιητές\\n\\nΗ Gaia παραδίδει αυτόματα όταν:\\n\\n- Ο επισκέπτης γράψει *\\"συνομιλία με άνθρωπο\\"* (ή οποιαδήποτε τοπική παραλλαγή).\\n- Η ίδια ερώτηση τεθεί δύο φορές χωρίς επίλυση.\\n- Η πρόθεση του επισκέπτη ταιριάζει με κανόνα δρομολόγησης (π.χ. χρέωση → ομάδα οικονομικών).\\n\\n## Δρομολόγηση\\n\\nΡυθμίστε το **Δρομολόγηση → Κανόνες** για να κατευθύνετε συγκεκριμένες προθέσεις σε συγκεκριμένες ομάδες ή χειριστές. Υποστηρίζονται τόσο το round-robin όσο και το λιγότερο φορτωμένο.\\n\\n## Εκτός ωραρίου\\n\\nΑν δεν υπάρχει συνδεδεμένος χειριστής, η Gaia προσφέρει φόρμα επανάκλησης ή παράδοσης μέσω email αντί να προσποιείται ότι κάποιος είναι διαθέσιμος."},"demo-article-crm":{"title":"Συγχρονισμός συνομιλιών με το CRM σας","excerpt":"Στείλτε κάθε συνομιλία σε HubSpot, Salesforce ή Pipedrive.","body":"## Υποστηριζόμενα CRM\\n\\n- HubSpot (OAuth)\\n- Salesforce (OAuth)\\n- Pipedrive (διακριτικό API)\\n- Προσαρμοσμένο μέσω webhooks\\n\\n## Τι συγχρονίζεται\\n\\n- Οι νέες συνομιλίες δημιουργούν μια επαφή (αν δεν υπάρχει ήδη) και μια σημείωση.\\n- Οι απαντήσεις των χειριστών προστίθενται στη χρονολογία της επαφής.\\n- Οι ετικέτες που εφαρμόζονται στο wexio αντικατοπτρίζονται στο CRM.\\n\\n## Αμφίδρομα\\n\\nΟι σημειώσεις χειριστών που προστίθενται στο CRM μπορούν να επιστρέψουν στο wexio μέσω του δέκτη webhook - δείτε *Ενσωματώσεις → Webhooks → Εισερχόμενα*."},"demo-article-shortcuts":{"title":"Συντομεύσεις πληκτρολογίου για χειριστές","excerpt":"Ταξινομήστε διπλάσια γρήγορα - χωρίς ποντίκι.","body":"## Πλοήγηση στα εισερχόμενα\\n\\n- `j` / `k` - επόμενη / προηγούμενη συνομιλία\\n- `e` - επίλυση\\n- `a` - ανάθεση σε εμένα\\n- `s` - αναβολή\\n\\n## Επεξεργαστής\\n\\n- `Cmd+Enter` - αποστολή\\n- `/` - άνοιγμα επιλογέα αποθηκευμένων απαντήσεων\\n- `Cmd+K` - παλέτα εντολών (τα πάντα)\\n\\n## Συμβουλή\\n\\nΤοποθετήστε τον δείκτη πάνω από οποιοδήποτε κουμπί στον πίνακα ελέγχου - η επεξήγηση εμφανίζει τη συντόμευσή του."}},"tags":{"setup":"Ρύθμιση","install":"Εγκατάσταση","automation":"Αυτοματισμός","flows":"Flows","integrations":"Ενσωματώσεις","slack":"Slack","billing":"Χρέωση","plans":"Πακέτα","design":"Σχεδιασμός","ai":"ΑΙ","crm":"CRM","productivity":"Παραγωγικότητα","inbox":"Εισερχόμενα"}}'),r={visitorName:`Εσείς`,messages:{"m-demo-1":{text:`Γεια σας 👋 Είμαι η Gaia, η ΑΙ του Wexio. Πώς μπορώ να βοηθήσω;`,ageLabel:`9:41 π.μ.`,buttons:[`Πώς λειτουργεί η τιμολόγηση;`,`Τι μπορεί να κάνει;`,`Συνομιλία με άνθρωπο`]},"m-demo-2":{text:`Μπορείτε να μου δείξετε πώς μοιάζει το widget;`,ageLabel:`9:41 π.μ.`},"m-demo-3":{text:``,ageLabel:`9:42 π.μ.`,mediaAlts:[`Στιγμιότυπο του προϊόντος`]},"m-demo-4":{text:``,ageLabel:`9:42 π.μ.`,mediaAlts:[`Περιστρεφόμενη υδρόγειος`]},"m-demo-5":{text:`Τέλεια! 😄 Ορίστε μερικές όψεις από την ομάδα μας.`,ageLabel:`9:43 π.μ.`},"m-demo-6":{text:`Μερικά highlights του πίνακα ελέγχου`,ageLabel:`9:43 π.μ.`,mediaAlts:[`Επισκόπηση πίνακα ελέγχου`,`Αναλύσεις`,`Εισερχόμενα`,`Αναφορές`]},"m-demo-7":{text:``,ageLabel:`9:44 π.μ.`,mediaAlts:[`Γρήγορη ξενάγηση`]},"m-demo-8":{text:``,ageLabel:`9:44 π.μ.`,mediaAlts:[`Φωνητικό μήνυμα`]},"m-demo-9":{text:``,ageLabel:`9:45 π.μ.`,mediaAlts:[`Οδηγός έναρξης`]},"m-demo-9b":{text:``,ageLabel:`9:45 π.μ.`,mediaAlts:[`Ενσωματώσεις Wexio`]},"m-demo-10":{text:`Έτοιμοι να το δοκιμάσετε μόνοι σας;`,ageLabel:`9:45 π.μ.`,buttons:[`Άνοιγμα sandbox`,`Κλείστε μια κλήση`,`Συνέχεια συνομιλίας`]}}},i={messengerDescription:`Η ομάδα μας μπορεί επίσης να βοηθήσει`,messengerMessage:`Γεια σας 👋 Ρωτήστε μας οτιδήποτε ή διαλέξτε μια γρήγορη ενέργεια.`},a={welcome:{system:`Συνομιλείτε τώρα με τη Gaia, τη βοηθό ΑΙ μας.`,hint:`Συμβουλή: επισυνάψτε ένα αρχείο ή ηχογραφήστε φωνητικό μήνυμα οποιαδήποτε στιγμή.`,greeting:`Γεια σας 👋 Είμαι η Gaia, η ΑΙ του Wexio. Ρωτήστε με οτιδήποτε ή διαλέξτε μια γρήγορη ενέργεια για να ξεκινήσετε.`},replies:{pricing:{text:`Το Wexio είναι δωρεάν για ένα widget· τα επί πληρωμή πακέτα ξεκινούν από 39 $/μήνα και ξεκλειδώνουν αυτοματισμούς, ενσωματώσεις και white-label.`,planBtn:`Προβολή επιπέδων πακέτων`,salesBtn:`Συνομιλία με τις πωλήσεις`},gaia:{text:`Η Gaia είναι ο πράκτορας ΑΙ που απαντά άμεσα στις ερωτήσεις των επισκεπτών. Μαθαίνει από τα άρθρα βοήθειάς σας και παραδίδει σε άνθρωπο όταν δεν μπορεί να βοηθήσει.`,handoffBtn:`Πώς λειτουργεί η παράδοση;`},human:{text:`Φυσικά - φέρνω στη συζήτηση τον Alex από την ομάδα. Θα απαντήσει σε λίγα λεπτά κατά τις ώρες λειτουργίας.`},fallback:{text:`Κατάλαβα - θα το ελέγξω και θα επανέλθω σε λίγο.`},voice:{text:`Έλαβα το φωνητικό σας μήνυμα - θα το ελέγξω και θα επανέλθω.`}}},o={main:`Έτοιμοι να το δοκιμάσετε μόνοι σας;`,billing:`Ευχαριστώ! Προώθησα την ερώτησή σας για το τιμολόγιο στην ομάδα χρέωσης.`,integrations:`Πώς συνδέω το WhatsApp στον λογαριασμό μου;`},s={recentMessage:e,news:t,help:n,conversation:r,playgroundDefaults:i,messenger:a,threads:o};export{r as conversation,s as default,n as help,a as messenger,t as news,i as playgroundDefaults,e as recentMessage,o as threads};
